using System;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Windows.Forms;using System.Xml.Serialization;
namespace ShotOut {partial class Editor {
string imageSavePath,projectSavePath;DateTime documentCreatedUtc=DateTime.UtcNow;
void PrepareDocumentSave(){AcceptCut();FinishBackgroundAdjustment();FinishImageAdjustment();FinishInlineText(true);FinishCloneStroke();FinishStrokeAdjustment();}
static void WriteFileSafely(string path,Action<Stream> write){path=Path.GetFullPath(path);string temp=Path.Combine(Path.GetDirectoryName(path),".shotout-"+Guid.NewGuid().ToString("N")+".tmp");try{using(var stream=File.Create(temp))write(stream);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
static ImageFormat ImageFormatForPath(string path){switch(Path.GetExtension(path).ToLowerInvariant()){case ".jpg":case ".jpeg":return ImageFormat.Jpeg;case ".bmp":return ImageFormat.Bmp;case ".gif":return ImageFormat.Gif;case ".tif":case ".tiff":return ImageFormat.Tiff;default:return ImageFormat.Png;}}
void WriteCurrentImage(string path,int? jpegQuality=null){PrepareDocumentSave();var format=ImageFormatForPath(path);using(var image=Art.Render(Background,Marks)){if(format.Guid==ImageFormat.Jpeg.Guid){using(var flat=Blank(image.Width,image.Height)){using(var graphics=Graphics.FromImage(flat))graphics.DrawImageUnscaled(image,0,0);WriteFileSafely(path,stream=>JpegOutput.Save(flat,stream,jpegQuality??Preferences.Current.ExportJpegQuality));}}else WriteFileSafely(path,stream=>image.Save(stream,format));}imageSavePath=Path.GetFullPath(path);if(projectSavePath==null)fileName=Path.GetFileName(path);dirty=false;ProjectHistory.RememberAsset(path);RefreshScreenshotBrowser();UpdateStatus("Image saved.");}
void WriteCurrentProject(string path){PrepareDocumentSave();var snapshot=Snapshot();WriteFileSafely(path,stream=>new XmlSerializer(typeof(Project)).Serialize(stream,snapshot));projectSavePath=Path.GetFullPath(path);fileName=Path.GetFileName(path);dirty=false;RecordRecentProject(path);UpdateStatus("Editable project saved.");}
string NewScreenshotPath(){string folder=ScreenshotMonthDirectory(documentCreatedUtc,true),name=CaptureFileNames.Name(Preferences.Current.ScreenshotPattern,documentCreatedUtc),extension=CaptureFileNames.Extension(Preferences.Current.ScreenshotFormat),path=Path.Combine(folder,name+extension);for(int suffix=2;File.Exists(path);suffix++)path=Path.Combine(folder,name+" ("+suffix+")"+extension);return path;}
bool SaveCurrentDocument(){if(welcomeRequested){UpdateStatus("Open an image or start a blank canvas first.");return false;}if(!String.IsNullOrEmpty(projectSavePath)){WriteCurrentProject(projectSavePath);return true;}WriteCurrentImage(String.IsNullOrEmpty(imageSavePath)?NewScreenshotPath():imageSavePath);return true;}
void SaveImageAs(){if(welcomeRequested)return;PrepareDocumentSave();using(var dialog=new SaveFileDialog {Title="Save image as",InitialDirectory=String.IsNullOrEmpty(imageSavePath)?ScreenshotMonthDirectory(documentCreatedUtc,true):Path.GetDirectoryName(imageSavePath),Filter="PNG image|*.png|JPEG image|*.jpg|Bitmap|*.bmp",FileName=Path.GetFileNameWithoutExtension(fileName)+".png",AddExtension=true,OverwritePrompt=true})if(dialog.ShowDialog(this)==DialogResult.OK)WriteCurrentImage(dialog.FileName);}
void SaveProjectAs(){if(welcomeRequested)return;PrepareDocumentSave();using(var dialog=new SaveFileDialog {Title="Save editable project",InitialDirectory=String.IsNullOrEmpty(projectSavePath)?ProjectDirectory(true):Path.GetDirectoryName(projectSavePath),Filter="Editable ShotOut project|*.shotout",FileName=Path.GetFileNameWithoutExtension(fileName)+".shotout",AddExtension=true,OverwritePrompt=true})if(dialog.ShowDialog(this)==DialogResult.OK)WriteCurrentProject(dialog.FileName);}
void ShowSaveAsMenu(){var menu=DarkMenu();menu.Items.Add("Save image as…",null,delegate{PopupLifetime.AfterClick(this,delegate{Guard(SaveImageAs);});});menu.Items.Add("Save editable project as…",null,delegate{PopupLifetime.AfterClick(this,delegate{Guard(SaveProjectAs);});});menu.Show(Cursor.Position);}
}}